public class Entities_escape_TriageGen2Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }









    @Test
    public void testEscape_HighAsciiNonEntity() throws IOException {
        StringWriter writer = new StringWriter();
        // Character > 0x7F that is NOT a named entity
        // 0x80 is 128 in decimal
        char highChar = '\u0080';
        entities.escape(writer, String.valueOf(highChar));
        Assert.assertEquals("&#128;", writer.toString());
    }






}

package org.apache.commons.lang;

import java.io.*;
