import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Entities_escape_TriageGen2Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }











    @Test
    public void testEscape_MixedContent() throws IOException {
        StringWriter writer = new StringWriter();
        // Mix: standard char, named entity, and high-ascii non-entity
        // Using '<' (likely entity), 'a' (ascii), and '\u00A9' (Copyright, often an entity or high-ascii)
        // To ensure branch coverage for c > 0x7F and entityName != null:
        // 1. c <= 0x7F && entityName == null (e.g., 'a')
        // 2. c <= 0x7F && entityName != null (e.g., '<')
        // 3. c > 0x7F && entityName == null (e.g., '\u0080')
        // 4. c > 0x7F && entityName != null (e.g., '\u00A9' if it's a named entity)

        // We'll force specific branches by using a custom entity via addEntity if possible, 
        // but here we use known logic.
        entities.addEntity("custom", 123); 
        // Note: the escape method uses entityName(char), which takes a char.

        entities.escape(writer, "a< \u0080");
        String result = writer.toString();

        // 'a' -> 'a'
        // '<' -> '&lt;' (likely)
        // ' ' -> ' '
        // '\u0080' -> '&#128;'
        Assert.assertTrue(result.contains("a"));
        Assert.assertTrue(result.contains("&#128;"));
    }




}

package org.apache.commons.lang;

import java.io.*;
