import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Entities_escape_TriageGen2Test {

    private Entities entities;

    @Before
    public void setUp() {
        entities = new Entities();
    }













    @Test
    public void testEscape_AllBranches() throws IOException {
        StringWriter writer = new StringWriter();

        // Branch 1: entityName != null (Named entity)
        // Branch 2: entityName == null && c > 0x7F (Numeric entity)
        // Branch 3: entityName == null && c <= 0x7F (Plain char)

        // We use '<' for Branch 1 (assuming it's defined)
        // We use '\u0080' for Branch 2
        // We use 'z' for Branch 3
        entities.escape(writer, "<z\u0080");

        String result = writer.toString();

        // Verify Branch 1: starts with & and ends with ;
        Assert.assertTrue("Should contain named entity format", result.contains("&") && result.contains(";"));
        // Verify Branch 3: contains z
        Assert.assertTrue("Should contain plain char", result.contains("z"));
        // Verify Branch 2: contains &#128;
        Assert.assertTrue("Should contain numeric entity format", result.contains("&#128;"));
    }


}

